receipt.legacy_source:
[[|
let manager := [Module clone]; [manager libDir: "/captured"];
let alias := manager;
[Globals at: #main put: [|
  [System gc];
  [System println: [manager == alias]];
  [System println: [manager libDir]];
  [alias libDir: "/changed"]; [System gc]; [System println: [manager libDir]];
  [System println: [[Module libDir] = "/private/tmp/birnam-reflect-slots/final-prefix/lib"]];
  [System println: [[db currentValue: manager attr: #libDir] = "/changed"]]
]];
[Module libDir: "/old-install/lib"];
[System saveImage: "/var/folders/f3/n4drgs5d7f3f6zxxxd2snx6m0000gn/T/birnam-reflect-slots-thbcxm6z/legacy.image"]; [System println: [[System imageSaveReport] status]]
] value]

receipt.new_source:
[[|
let manager := [Module clone]; [manager libDir: "/captured"];
let alias := manager;
[Globals at: #main put: [|
  [System gc];
  [System println: [manager == alias]];
  [System println: [manager libDir]];
  [alias libDir: "/changed"]; [System gc]; [System println: [manager libDir]];
  [System println: [[Module libDir] = "/private/tmp/birnam-reflect-slots/final-prefix/lib"]];
  [System println: [[[Reflect slotsOf: manager] at: 0] at: #name]];
 [Reflect slot: #libDir in: manager put: "/reflected"];
 [System println: [manager libDir]];
 [System println: [[db currentValue: manager attr: #libDir] isNil]]
]];
[Module libDir: "/old-install/lib"];
[System saveImage: "/var/folders/f3/n4drgs5d7f3f6zxxxd2snx6m0000gn/T/birnam-reflect-slots-thbcxm6z/new.image"]; [System println: [[System imageSaveReport] status]]
] value]
